"""配送業者ごとの追跡番号の形式。"""
import re

PATTERNS = {"A 運輸": re.compile(r"\d{12}")}


def is_valid(carrier: str, number: str) -> bool:
    pattern = PATTERNS.get(carrier)
    return bool(pattern and pattern.fullmatch(number))
